// Module-level cache so re-renders do not refetch; unservable repos resolve to [].
const _previewCache = new Map<string, Promise<string[]>>();

async function fetchPreviews(repo: string): Promise<string[]> {
  if (!hasDatasetsServer()) return [];
  // Keyed by server too, so an empty result is retried against a later mirror.
  const base = getHfDatasetsServerBase();
  const cacheKey = `${base}::${repo}`;
  const cached = _previewCache.get(cacheKey);
  if (cached) return cached;
  const p = (async () => {
    try {
      const res = await hubFetch(
        `${base}/first-rows?dataset=${encodeURIComponent(
          repo,
        )}&config=default&split=train`,
      );
      if (!res.ok) return [];
      const data = (await res.json()) as {
        features?: { name: string; type?: { _type?: string } }[];
        rows?: { row: Record<string, unknown> }[];
      };
      const imageCol = data.features?.find((f) => f.type?._type === "Image")?.name;
      if (!imageCol || !data.rows) return [];
      const urls: string[] = [];
      for (const r of data.rows) {
        const cell = r.row[imageCol] as { src?: string } | undefined;
        if (cell?.src) urls.push(cell.src);
        if (urls.length >= 3) break;
      }
      return urls;
    } catch {
      return [];
    }
  })();
  _previewCache.set(cacheKey, p);
  return p;
}

export function shortExampleLabel(label: string): string {
  return label.replace(/\s*\(.*$/, "");
}

function ExamplePreviews({ repo }: { repo: string }) {
  const [urls, setUrls] = useState<string[] | null>(null);
  const hfDatasetsServer = useHfDatasetsServer();
  const hubSource = useHubSource();
  useEffect(() => {
    let cancelled = false;
    void fetchPreviews(repo).then((u) => {
      if (!cancelled) setUrls(u);
    });
    return () => {
      cancelled = true;
    };
  }, [repo, hfDatasetsServer, hubSource]);

  if (!urls || urls.length === 0) return null;
  return (
    <div className="flex gap-1">
      {urls.map((u) => (
        <div key={u} className="h-9 w-12 shrink-0 overflow-hidden rounded-sm bg-muted">
          <img src={u} alt="" loading="lazy" className="size-full object-cover" />
        </div>
      ))}
    </div>
  );
}

export function ExampleDatasetCards({
  examples,
  busyId,
